const task = $('Extract Task JSON').item.json.task;
const required = [
  'schema_version','task_id','title','owner','state','phase',
  'requires_human_approval','production_mutation','evidence','audit'
];
const errors = [];

for (const key of required) {
  if (!(key in task)) errors.push(`missing field: ${key}`);
}
if (task.production_mutation !== false) {
  errors.push('production_mutation must be false in PILOT phase');
}
if (typeof task.audit !== 'object' || !('status' in (task.audit||{}))) {
  errors.push('audit structure invalid');
}
if (!Array.isArray(task.evidence)) {
  errors.push('evidence must be an array');
}

return [{
  json: {
    valid: errors.length === 0,
    errors,
    task
  }
}];

const valid = $json.valid;
const errors = $json.errors || [];
const task = $json.task;
const taskId = $('Webhook').item.json.body.task_id;

const bodyRaw = $('Webhook').item.json.body;
const payloadSignature = JSON.stringify(bodyRaw);

let evidenceRaw = '';
try {
  evidenceRaw = $('Extract Evidence Text').item.json.evidence_raw || '';
} catch (e) {
  evidenceRaw = '';
}

const lines = evidenceRaw.split('\n').map(l => l.trim()).filter(l => l.length > 0);
let lastEntry = null;
if (lines.length > 0) {
  try {
    lastEntry = JSON.parse(lines[lines.length - 1]);
  } catch (e) {
    lastEntry = null;
  }
}

const currentState = task.automation ? task.automation.state : null;

const executionId = $execution.id;
const transitionId = `${taskId}#${String(executionId).padStart(4, '0')}`;

let isConflict = false;
let isDuplicate = false;

if (lastEntry && lastEntry.payload_signature === payloadSignature) {
  isDuplicate = true;
} else if (lastEntry && lastEntry.payload_signature !== payloadSignature && currentState) {
  isConflict = true;
}

const newState = valid ? 'VALIDATION_PASSED' : 'FAILED';
const failureCode = valid ? null : 'VALIDATION_FAILED';

const ALLOWED_FROM = {
  VALIDATION_PASSED: [null, 'RECEIVED'],
  FAILED: [null, 'RECEIVED', 'VALIDATION_PASSED']
};
const isIllegalTransition = !!currentState && !(ALLOWED_FROM[newState] || []).includes(currentState);

const updatedTask = Object.assign({}, task, {
  automation: {
    state: newState,
    failure_code: failureCode,
    last_transition_id: transitionId
  }
});

const evidenceEntry = {
  transition_id: transitionId,
  task_id: taskId,
  from: currentState || 'RECEIVED',
  to: newState,
  failure_code: failureCode,
  actor: 'automation',
  payload_signature: payloadSignature,
  execution_id: executionId,
  timestamp: new Date().toISOString(),
  reason: valid ? 'schema validation passed' : errors.join('; ')
};

return [{
  json: {
    isConflict,
    isDuplicate,
    isIllegalTransition,
    valid,
    task_id: taskId,
    currentState,
    newState,
    updatedTask,
    evidenceLine: JSON.stringify(evidenceEntry),
    evidenceLineWithNewline: JSON.stringify(evidenceEntry) + '\n',
    currentAutomation: task.automation || null,
    transitionId,
    failureCode
  }
}];

const exitCode = $json.exitCode || 0;
const stdout = $json.stdout || '';

let state = null;
let failureCode = null;

if (exitCode === 0) {
  try {
    const result = JSON.parse(stdout);
    const regState = result.final_state;
    const MAPPING = {
      'QUALITY_PASSED': { state: 'COMPLETED', failure_code: null },
      'REGISTRATION_FAILED': { state: 'FAILED', failure_code: 'REGISTRATION_FAILED' },
      'RAW_CHECKSUM_MISMATCH': { state: 'FAILED', failure_code: 'RAW_CHECKSUM_MISMATCH' },
      'EXTRACTION_FAILED': { state: 'FAILED', failure_code: 'EXTRACTION_FAILED' },
      'QUALITY_GATE_FAILED': { state: 'FAILED', failure_code: 'QUALITY_GATE_FAILED' }
    };
    const mapped = MAPPING[regState];
    if (mapped) {
      state = mapped.state;
      failureCode = mapped.failure_code;
    } else {
      state = 'FAILED';
      failureCode = 'INTERNAL_STATE_MAPPING_ERROR';
    }
  } catch (e) {
    state = 'FAILED';
    failureCode = 'PARSE_ERROR';
  }
} else if (exitCode === 1) {
  state = 'FAILED'; failureCode = 'FILE_ERROR';
} else if (exitCode === 2) {
  state = 'FAILED'; failureCode = 'VALIDATION_FAILED';
} else if (exitCode === 3) {
  state = 'FAILED'; failureCode = 'RAW_CHECKSUM_MISMATCH';
} else {
  state = 'FAILED';
  failureCode = 'INTERNAL_STATE_MAPPING_ERROR';
}

return [{ json: { exitCode, stdout, newState: state, newFailureCode: failureCode, task_id: $('Code — Decide Transition').item.json.task_id, transitionId: $('Code — Decide Transition').item.json.transitionId } }];
